def _operator(st):
    from scipy import sparse
    (nx, ny) = (st['nx'], st['ny'])
    ax = _axis(st['kappa_x'], st['vel_x'], st['Lx'] / (nx - 1))
    ay = _axis(st['kappa_y'], st['vel_y'], st['Ly'] / (ny - 1))
    return sparse.kron(sparse.eye(ny), ax, format='csc') + sparse.kron(ay, sparse.eye(nx), format='csc') + sparse.diags(st['V_reaction_2d'].ravel(order='F'), format='csc')

def _calibrate(st):
    sweeps = st['sensor_calibration_sweeps']
    (ref, raw) = (sweeps['ref_rosette'], sweeps['raw_rosette'])
    fit = np.linalg.lstsq(np.column_stack((ref, np.ones(len(ref)))), raw, rcond=None)[0]
    obs = st['y_obs_raw'].reshape(-1, 4)
    return np.linalg.solve(fit[:4].T, (obs - fit[4]).T).T.ravel()

def _project(st, S, y):
    Z = st['Z_nuisance']
    ztz = Z.T @ Z + st['nuisance_ridge'] * np.eye(Z.shape[1])
    proj = np.linalg.solve(ztz, Z.T @ np.column_stack((S, y)))
    projected = np.column_stack((S, y)) - Z @ proj
    return (projected[:, :-1], projected[:, -1])

def _qp(A, b, ridge, cap, budget):
    from scipy.optimize import minimize
    n = A.shape[1]
    (H, c) = (A.T @ A + ridge * np.eye(n), A.T @ b)

    def grad(w):
        return H @ w - c
    if budget == 0 or budget == n * cap:
        w = np.full(n, budget / n)
        return (w, float(np.min(grad(w)) if budget == 0 else np.max(grad(w))))
    scale = np.linalg.norm(H, ord=np.inf)
    res = minimize(lambda w: (0.5 * w @ H @ w - c @ w) / scale, np.full(n, budget / n), jac=lambda w: grad(w) / scale, bounds=[(0.0, cap)] * n, method='SLSQP', constraints={'type': 'eq', 'fun': lambda w: w.sum() - budget, 'jac': lambda w: np.ones(n)}, options={'ftol': 1e-13, 'maxiter': 500})
    w = res.x.copy()
    (lower, upper) = (w <= 1e-08 * cap, w >= (1 - 1e-08) * cap)
    free = ~(lower | upper)

    def multiplier(v):
        g = grad(v)
        mask = (v > 1e-09 * cap) & (v < (1 - 1e-09) * cap)
        if np.any(mask):
            return float(np.mean(g[mask]))
        return float(np.clip(0.0, np.max(g[v > cap / 2]), np.min(g[v <= cap / 2])))

    def gap(v, nu):
        d = grad(v) - nu
        return d.clip(0) @ v + (-d).clip(0) @ (cap - v)
    nu = multiplier(w)
    if np.any(free):
        v = np.where(upper, cap, 0.0)
        hf = H[np.ix_(free, free)]
        lin = c[free] - H[free] @ v
        (x, p) = np.linalg.solve(hf, np.column_stack((lin, np.ones(len(lin))))).T
        mu = (budget - v.sum() - x.sum()) / p.sum()
        v[free] = x + mu * p
        if np.min(v) >= 0.0 and np.max(v) <= cap and (gap(v, mu) <= gap(w, nu)):
            (w, nu) = (v, float(mu))
    return (w, nu)
